42	class WorksPageDomRuntime {
43	  private readonly _root: ParentNode;
44	
45	  constructor(root: ParentNode) {
46	    this._root = root;
47	  }
48	
49	  resolve(): WorksPageElements {
50	    return {
51	      root: this._queryElement<HTMLElement>(WORK_PAGE_DOM.rootSelector),
52	      canvas: this._queryCanvasElement(WORK_CANVAS_CONFIG.canvasId),
53	      grid: this._queryElement<HTMLElement>(WORK_PAGE_DOM.gridSelector),
54	      gridList: this._queryElement<HTMLUListElement>(
55	        WORK_PAGE_DOM.gridListSelector,
56	      ),
57	      gridPagination: this._queryElement<HTMLElement>(
58	        WORK_PAGE_DOM.gridPaginationSelector,
59	      ),
60	      controls: this._queryElement<HTMLElement>(WORK_PAGE_DOM.controlsSelector),
61	      toggle: this._queryElement<HTMLElement>(WORK_PAGE_DOM.toggleSelector),
62	      filterWrap: this._queryElement<HTMLElement>(
63	        WORK_PAGE_DOM.filterWrapSelector,
64	      ),
65	      gridFilterWrap: this._queryElement<HTMLElement>(
66	        WORK_PAGE_DOM.gridFilterWrapSelector,
67	      ),
68	      filterButton: this._queryElement<HTMLButtonElement>(
69	        WORK_PAGE_DOM.filterButtonSelector,
70	      ),
71	      filterPanel: this._queryElement<HTMLElement>(
72	        WORK_PAGE_DOM.filterPanelSelector,
73	      ),
74	      dragHint: this._queryElement<HTMLElement>(WORK_PAGE_DOM.dragHintSelector),
75	    };
76	  }
77	
78	  readState(elements: WorksPageElements): WorksPageState {
79	    const root = elements.root;
80	    const viewRaw = root?.dataset.view;
81	    const view: WorksViewMode =
82	      viewRaw === "grid" || viewRaw === "scatter"
83	        ? viewRaw
84	        : WORK_PAGE_STATE_DEFAULT.view;
85	    const categoryRaw = root?.dataset.category?.trim() ?? "";
86	    const pageRaw = Number.parseInt(root?.dataset.page ?? "", 10);
87	    const limitRaw = Number.parseInt(root?.dataset.limit ?? "", 10);
88	
89	    return {
90	      view,
91	      category: categoryRaw.length > 0 ? categoryRaw : null,
92	      page:
93	        Number.isFinite(pageRaw) && pageRaw > 0
94	          ? pageRaw
95	          : WORK_PAGE_STATE_DEFAULT.page,
96	      limit:
97	        Number.isFinite(limitRaw) && limitRaw > 0
98	          ? limitRaw
99	          : WORK_PAGE_STATE_DEFAULT.limit,
100	    };
101	  }
102	
103	  private _queryElement<TElement extends HTMLElement>(
104	    selector: string,
105	  ): TElement | null {
106	    return this._root.querySelector<TElement>(selector);
107	  }
108	
109	  private _queryCanvasElement(canvasId: string): HTMLCanvasElement | null {
110	    return this._root.querySelector<HTMLCanvasElement>(`#${canvasId}`);
111	  }
112	}
