157	class WorksPageUiRuntime {
158	  private readonly _elements: WorksPageElements;
159	  private _gridEnterRafId: number | null = null;
160	  private _toggleRevealRafId: number | null = null;
161	  private _toggleRevealTimeoutId: number | null = null;
162	  private _dragHintTimeoutId: number | null = null;
163	  private _dragHintDeactivateTimeoutId: number | null = null;
164	  private _dragHintExitTimeoutId: number | null = null;
165	
166	  constructor(elements: WorksPageElements) {
167	    this._elements = elements;
168	  }
169	
170	  applyInitialState(state: WorksPageState): void {
171	    this.hideViewToggle();
172	    this.hideDragHint();
173	    if (state.view === "grid") {
174	      this.showGrid();
175	      return;
176	    }
177	    this.hideGrid();
