184	
185	  enterGrid(): void {
186	    this.hideIntroIfReady();
187	    this.showGrid();
188	    this.showViewToggle();
189	    const grid = this._elements.grid;
190	    if (!grid) return;
191	    grid.classList.remove(WORK_PAGE_DOM.gridEnterClass);
192	    this._gridEnterRafId = FrameScheduler.request(() => {
193	      this._elements.grid?.classList.add(WORK_PAGE_DOM.gridEnterClass);
