197	
198	  scheduleViewToggleReveal(delayMs: number): void {
199	    if (this._toggleRevealTimeoutId !== null) {
200	      window.clearTimeout(this._toggleRevealTimeoutId);
201	      this._toggleRevealTimeoutId = null;
202	    }
203	    if (this._toggleRevealRafId !== null) {
204	      FrameScheduler.cancel(this._toggleRevealRafId);
205	      this._toggleRevealRafId = null;
206	    }
207	    this._toggleRevealTimeoutId = window.setTimeout(
208	      () => {
209	        this._toggleRevealTimeoutId = null;
210	        this._toggleRevealRafId = FrameScheduler.request(() => {
211	          this.showViewToggle();
212	          this._toggleRevealRafId = null;
213	        });
214	      },
215	      Math.max(0, delayMs),
216	    );
217	  }
218	
219	  showViewToggle(): void {
220	    const controls = this._elements.controls;
221	    if (!controls) return;
222	    this._elements.root?.setAttribute("data-ui-ready", "true");
223	    controls.hidden = false;
224	    controls.dataset.ready = "true";
225	    controls.removeAttribute("inert");
226	    Aria.setHidden(controls, false);
227	  }
228	
229	  hideViewToggle(): void {
230	    const controls = this._elements.controls;
231	    if (!controls) return;
232	    this._elements.root?.setAttribute("data-ui-ready", "false");
233	    controls.hidden = true;
234	    controls.dataset.ready = "false";
235	    controls.setAttribute("inert", "");
236	    Aria.setHidden(controls, true);
237	  }
238	
239	  showGrid(): void {
240	    this._syncViewAttributes("grid");
241	    const grid = this._elements.grid;
242	    if (!grid) return;
243	    grid.hidden = false;
244	    grid.classList.remove("is-hidden");
245	    Aria.setHidden(grid, false);
246	  }
247	
248	  hideGrid(): void {
249	    this._syncViewAttributes("scatter");
250	    const grid = this._elements.grid;
251	    if (!grid) return;
252	    grid.hidden = true;
253	    grid.classList.add("is-hidden");
254	    Aria.setHidden(grid, true);
