256	
257	  hideCanvas(): void {
258	    const canvas = this._elements.canvas;
259	    if (!canvas) return;
260	    canvas.classList.add("is-hidden");
261	    Aria.setHidden(canvas, true);
262	  }
263	
264	  showCanvas(): void {
265	    const canvas = this._elements.canvas;
266	    if (!canvas) return;
267	    canvas.classList.remove("is-hidden");
268	    Aria.setHidden(canvas, false);
269	  }
270	
271	  syncFilterSelection(
272	    category: string | null,
273	    options?: { animateLabel?: boolean },
274	  ): void {
275	    const filterButton = this._elements.filterButton;
276	    const filterPanel = this._elements.filterPanel;
277	    if (!filterButton || !filterPanel) return;
278	    const optionNodes = filterPanel.querySelectorAll<HTMLElement>(
279	      WORK_PAGE_DOM.filterOptionSelector,
280	    );
281	    let activeLabel = "전체";
282	    optionNodes.forEach((option) => {
283	      const optionCategory = option.dataset.category?.trim() ?? "";
284	      const isActive =
285	        (category === null && optionCategory.length === 0) ||
286	        optionCategory === (category ?? "");
287	      option.classList.toggle("is-active", isActive);
288	      option.setAttribute("aria-pressed", isActive ? "true" : "false");
289	      if (!isActive) return;
290	      activeLabel =
291	        option.dataset.label?.trim() || option.textContent?.trim() || "전체";
292	    });
293	    const labelElement = filterButton.querySelector<HTMLElement>(
294	      ".no-works-canvas__filter-button-label",
295	    );
296	    if (!labelElement) return;
297	    const previousLabel = labelElement.textContent ?? "";
298	    const shouldAnimate =
299	      options?.animateLabel === true && previousLabel !== activeLabel;
300	
301	    if (!shouldAnimate) {
302	      labelElement.textContent = activeLabel;
303	      return;
304	    }
305	
306	    filterButton.classList.remove("is-filter-label-entering");
307	    filterButton.classList.add("is-filter-label-leaving");
308	    window.setTimeout(() => {
309	      labelElement.textContent = activeLabel;
310	      filterButton.classList.remove("is-filter-label-leaving");
311	      filterButton.classList.add("is-filter-label-entering");
312	      window.setTimeout(() => {
313	        filterButton.classList.remove("is-filter-label-entering");
314	      }, WORKS_FILTER_TRANSITION_MS);
315	    }, WORKS_FILTER_TRANSITION_MS);
316	  }
317	
318	  syncViewLinks(category: string | null): void {
319	    const toggle = this._elements.toggle;
320	    if (!toggle) return;
321	    const links = toggle.querySelectorAll<HTMLAnchorElement>("a[href]");
322	    links.forEach((link) => {
323	      const url = new URL(link.href, window.location.origin);
324	      const view = url.searchParams.get("view") ?? "scatter";
325	      url.searchParams.set("view", view);
326	      if (category) {
327	        url.searchParams.set("category", category);
328	      } else {
329	        url.searchParams.delete("category");
330	      }
331	      link.href = `${url.pathname}${url.search}${url.hash}`;
332	    });
333	  }
334	
335	  showDragHint(): void {
336	    if (!WORK_HINT_CONFIG.enabled) return;
337	    this._clearDragHintTimers();
338	    const dragHint = this._elements.dragHint;
339	    if (!dragHint) return;
340	    dragHint.hidden = false;
341	    dragHint.classList.remove(WORK_PAGE_DOM.dragHintHidingClass);
342	    dragHint.classList.add(WORK_PAGE_DOM.dragHintVisibleClass);
343	    dragHint.removeAttribute("inert");
344	    Aria.setHidden(dragHint, false);
345	    this._dragHintTimeoutId = window.setTimeout(() => {
346	      this.hideDragHint();
347	    }, WORK_HINT_CONFIG.autoHideMs);
348	  }
349	
350	  showDragHintIfNeeded(state: WorksPageState): void {
351	    if (!WORK_HINT_CONFIG.enabled) return;
352	    if (state.view !== "scatter") return;
353	    this.showDragHint();
354	  }
355	
356	  hideDragHint(): void {
357	    this._clearDragHintTimers();
358	    const dragHint = this._elements.dragHint;
359	    if (!dragHint) return;
360	    dragHint.hidden = false;
361	    this._dragHintDeactivateTimeoutId = window.setTimeout(() => {
362	      dragHint.classList.remove(WORK_PAGE_DOM.dragHintVisibleClass);
363	      dragHint.classList.add(WORK_PAGE_DOM.dragHintHidingClass);
364	      this._dragHintDeactivateTimeoutId = null;
365	      this._dragHintExitTimeoutId = window.setTimeout(() => {
366	        dragHint.setAttribute("inert", "");
367	        Aria.setHidden(dragHint, true);
368	        dragHint.classList.remove(WORK_PAGE_DOM.dragHintHidingClass);
369	        this._dragHintExitTimeoutId = null;
370	      }, WORK_HINT_CONFIG.exitDurationMs);
371	    }, WORK_HINT_CONFIG.hideStartDelayMs);
372	  }
373	
374	  dispose(): void {
375	    if (this._gridEnterRafId !== null) {
376	      FrameScheduler.cancel(this._gridEnterRafId);
377	      this._gridEnterRafId = null;
378	    }
379	    if (this._toggleRevealRafId !== null) {
380	      FrameScheduler.cancel(this._toggleRevealRafId);
381	      this._toggleRevealRafId = null;
382	    }
383	    if (this._toggleRevealTimeoutId !== null) {
384	      window.clearTimeout(this._toggleRevealTimeoutId);
385	      this._toggleRevealTimeoutId = null;
386	    }
387	    this._clearDragHintTimers();
388	    this._resetDragHint();
389	    this._elements.grid?.classList.remove(WORK_PAGE_DOM.gridEnterClass);
390	  }
391	
392	  private _syncViewAttributes(view: WorksViewMode): void {
393	    this._elements.root?.setAttribute("data-view", view);
394	    this._elements.toggle?.setAttribute("data-view", view);
395	    const gfw = this._elements.gridFilterWrap;
396	    if (gfw) {
397	      const isGrid = view === "grid";
398	      Aria.setHidden(gfw, !isGrid);
399	      if (isGrid) {
400	        gfw.removeAttribute("hidden");
401	        gfw.removeAttribute("inert");
402	      } else {
403	        gfw.setAttribute("hidden", "");
404	        gfw.setAttribute("inert", "");
405	      }
406	    }
407	  }
408	
409	  private _clearDragHintTimers(): void {
410	    if (this._dragHintTimeoutId !== null) {
411	      window.clearTimeout(this._dragHintTimeoutId);
412	      this._dragHintTimeoutId = null;
413	    }
414	    if (this._dragHintExitTimeoutId !== null) {
415	      window.clearTimeout(this._dragHintExitTimeoutId);
416	      this._dragHintExitTimeoutId = null;
417	    }
418	    if (this._dragHintDeactivateTimeoutId !== null) {
419	      window.clearTimeout(this._dragHintDeactivateTimeoutId);
420	      this._dragHintDeactivateTimeoutId = null;
421	    }
422	  }
423	
424	  private _resetDragHint(): void {
425	    const dragHint = this._elements.dragHint;
426	    if (!dragHint) return;
427	    dragHint.hidden = true;
428	    dragHint.setAttribute("inert", "");
429	    dragHint.classList.remove(
430	      WORK_PAGE_DOM.dragHintVisibleClass,
431	      WORK_PAGE_DOM.dragHintHidingClass,
432	    );
433	    Aria.setHidden(dragHint, true);
434	  }
435	}
