437	class WorksGridFeedRuntime {
438	  private readonly _state: WorksPageState;
439	  private readonly _elements: WorksPageElements;
440	  private _feedState: WorksGridFeedState = {
441	    nextOffset: null,
442	    hasMore: false,
443	  };
444	  private _abortController: AbortController | null = null;
445	  private _loading = false;
446	  private _thresholdArmed = true;
447	  private _bound = false;
448	  private readonly _videoHoverCleanups: Array<() => void> = [];
449	  private _category: string | null;
450	  private _sentinel: HTMLDivElement | null = null;
451	  private _sentinelObserver: IntersectionObserver | null = null;
452	  private _filterModal: HTMLDivElement | null = null;
453	  private readonly _filterModalCleanups: Array<() => void> = [];
454	
455	  constructor(state: WorksPageState, elements: WorksPageElements) {
456	    this._state = state;
457	    this._elements = elements;
458	    this._category = state.category;
459	  }
460	
461	  async init(): Promise<void> {
462	    const list = this._elements.gridList;
463	    if (!list) return;
464	    this._clearList();
465	    this._feedState = {
466	      nextOffset: null,
467	      hasMore: false,
468	    };
469	    this._syncRootState();
470	    this._abortController?.abort();
471	    this._abortController = new AbortController();
472	    const grid = this._elements.grid;
473	    if (grid) grid.dataset.loading = "true";
474	    try {
475	      const response = await this._fetchItems(this._resolveInitialOffset());
476	      this._appendItems(response.items);
477	      this._feedState = {
478	        nextOffset: response.nextOffset,
479	        hasMore: response.hasMore,
480	      };
481	      this._syncRootState();
482	      this._syncPaginationVisibility();
483	      this._attachSentinel();
484	    } catch (error) {
485	      if (error instanceof DOMException && error.name === "AbortError") return;
486	      throw error;
487	    } finally {
488	      this._abortController = null;
489	      if (grid) delete grid.dataset.loading;
490	    }
491	  }
492	
493	  bind(): void {
494	    if (this._bound) return;
495	    window.addEventListener("scroll", this._handleScroll, { passive: true });
496	    this._bound = true;
497	    this._bindFilterModal();
498	  }
499	
500	  dispose(): void {
501	    if (this._bound) {
502	      window.removeEventListener("scroll", this._handleScroll);
503	      this._bound = false;
504	    }
505	    this._abortController?.abort();
506	    this._abortController = null;
507	    this._loading = false;
508	    this._thresholdArmed = true;
509	    this._runVideoHoverCleanups();
510	    this._detachSentinel();
511	    this._removeFilterModal();
512	  }
513	
514	  async changeCategory(category: string | null): Promise<void> {
515	    this._category = category;
516	    this._elements.root?.setAttribute("data-category", category ?? "");
517	    await this.init();
518	    this._syncFilterModalSelection(category);
519	  }
520	
521	  private readonly _handleScroll = (): void => {
522	    if (!this._feedState.hasMore) return;
523	    if (this._loading) return;
524	    const list = this._elements.gridList;
525	    if (!list) return;
526	    const thresholdReached = this._isThresholdReached(list);
527	    if (!thresholdReached) {
528	      this._thresholdArmed = true;
529	      return;
530	    }
531	    if (!this._thresholdArmed) return;
532	    this._thresholdArmed = false;
533	    void this._loadMore();
534	  };
535	
536	  private _isThresholdReached(list: HTMLElement): boolean {
537	    const rect = list.getBoundingClientRect();
538	    return (
539	      rect.bottom - ResponsiveRuntime.getDefault().getSnapshot().viewportHeight <=
540	        WORK_GRID_INFINITE_CONFIG.thresholdPx
541	    );
542	  }
543	
544	  private _attachSentinel(): void {
545	    this._detachSentinel();
546	    if (!this._feedState.hasMore) return;
547	    const list = this._elements.gridList;
548	    if (!list) return;
549	    const sentinel = document.createElement("div");
550	    sentinel.style.height = "1px";
551	    sentinel.setAttribute("aria-hidden", "true");
552	    list.after(sentinel);
553	    this._sentinel = sentinel;
554	    this._sentinelObserver = new IntersectionObserver(
555	      (entries) => {
556	        if (entries[0]?.isIntersecting) void this._loadMore();
557	      },
558	      { rootMargin: `${WORK_GRID_INFINITE_CONFIG.thresholdPx}px` },
559	    );
560	    this._sentinelObserver.observe(sentinel);
561	  }
562	
563	  private _detachSentinel(): void {
564	    this._sentinelObserver?.disconnect();
565	    this._sentinelObserver = null;
566	    this._sentinel?.remove();
567	    this._sentinel = null;
568	  }
569	
570	  private _bindFilterModal(): void {
571	    const filterPanel = this._elements.filterPanel;
572	    if (!filterPanel) return;
573	    const trigger = this._elements.root?.querySelector<HTMLButtonElement>(
574	      ".js-grid-filter-trigger",
575	    );
576	    if (!trigger) return;
577	
578	    const categories: Array<{ slug: string; label: string }> = [];
579	    filterPanel
580	      .querySelectorAll<HTMLElement>("[data-works-filter-option]")
581	      .forEach((el) => {
582	        categories.push({
583	          slug: el.dataset.category ?? "",
584	          label: el.dataset.label ?? el.textContent?.trim() ?? "",
585	        });
586	      });
587	    if (categories.length === 0) return;
588	
589	    const modal = document.createElement("div");
590	    modal.className = "no-grid-filter-modal";
591	    modal.setAttribute("aria-hidden", "true");
592	    modal.setAttribute("role", "dialog");
593	    modal.setAttribute("aria-label", "카테고리 필터");
594	
595	    const backdrop = document.createElement("div");
596	    backdrop.className = "no-grid-filter-modal__backdrop";
597	
598	    const sheet = document.createElement("div");
599	    sheet.className = "no-grid-filter-modal__sheet";
600	
601	    const header = document.createElement("div");
602	    header.className = "no-grid-filter-modal__header";
603	    const headerTitle = document.createElement("span");
604	    headerTitle.textContent = "Category";
605	    const closeBtn = document.createElement("button");
606	    closeBtn.type = "button";
607	    closeBtn.className = "no-grid-filter-modal__close";
608	    closeBtn.setAttribute("aria-label", "닫기");
609	    closeBtn.textContent = "✕";
610	    header.append(headerTitle, closeBtn);
611	
612	    const list = document.createElement("ul");
613	    list.className = "no-grid-filter-modal__list";
614	    categories.forEach(({ slug, label }) => {
615	      const li = document.createElement("li");
616	      const btn = document.createElement("button");
617	      btn.type = "button";
618	      btn.className = "no-grid-filter-modal__option";
619	      btn.dataset.category = slug;
620	      const rect = document.createElement("span");
621	      rect.className = "no-loop-filter-rect";
622	      rect.setAttribute("aria-hidden", "true");
623	      for (let i = 0; i < 4; i++) rect.append(document.createElement("span"));
624	      const labelSpan = document.createElement("span");
625	      labelSpan.textContent = label;
626	      btn.append(rect, labelSpan);
627	      li.append(btn);
