817	  private _attachVideoHover(
818	    li: HTMLLIElement,
819	    videoUrl: string,
820	    figure: HTMLElement,
821	  ): void {
822	    const video = document.createElement("video");
823	    video.muted = true;
824	    video.loop = true;
825	    video.playsInline = true;
826	    video.preload = "none";
827	    figure.append(video);
828	
829	    let isHovered = false;
830	    let pendingPlay: Promise<void> | null = null;
831	
832	    const show = (): void => {
833	      if (isHovered) figure.classList.add("is-video-active");
834	    };
835	
836	    const hideVideoNow = (): void => {
837	      figure.classList.remove("is-video-active");
838	    };
839	
840	    const safePause = (): void => {
841	      video.pause();
842	      video.currentTime = 0;
843	    };
844	
845	    const drainAndPause = (): void => {
846	      const p = pendingPlay;
847	      pendingPlay = null;
848	      if (p !== null) {
849	        void p.then(() => { if (!isHovered) safePause(); });
850	      } else {
851	        safePause();
852	      }
853	    };
854	
855	    const onEnter = (): void => {
856	      isHovered = true;
857	      if (!video.src) {
858	        video.src = videoUrl;
859	        video.load();
860	      }
861	      pendingPlay = video.play().catch(() => undefined);
862	      if (video.readyState >= 3) {
863	        show();
864	      } else {
865	        video.addEventListener("canplay", show, { once: true });
866	      }
867	    };
868	
869	    const onLeave = (): void => {
870	      isHovered = false;
871	      video.removeEventListener("canplay", show);
872	      hideVideoNow();
873	      drainAndPause();
874	    };
875	
876	    li.addEventListener("pointerenter", onEnter);
877	    li.addEventListener("pointerleave", onLeave);
878	
879	    this._videoHoverCleanups.push(() => {
880	      isHovered = false;
881	      video.removeEventListener("canplay", show);
882	      figure.classList.remove("is-video-active");
883	      drainAndPause();
884	      li.removeEventListener("pointerenter", onEnter);
885	      li.removeEventListener("pointerleave", onLeave);
886	    });
887	  }
