1439	      filterPanel.setAttribute("aria-hidden", "false");
1440	      filterPanel.classList.add("is-open");
1441	      filterButton.setAttribute("aria-expanded", "true");
1442	    };
1443	
1444	    const togglePanel = (): void => {
1445	      if (filterPanel.classList.contains("is-open")) {
