1447	      } else {
1448	        openPanel();
1449	      }
1450	    };
1451	
1452	    const onFilterButtonClick = (event: MouseEvent): void => {
1453	      event.stopPropagation();
1454	      togglePanel();
1455	    };
1456	    filterButton.addEventListener("click", onFilterButtonClick);
1457	    this._scatterFilterCleanup.push(() =>
1458	      filterButton.removeEventListener("click", onFilterButtonClick),
1459	    );
1460	
1461	    const onPanelClick = (event: MouseEvent): void => {
1462	      const target = event.target as HTMLElement | null;
1463	      const option = target?.closest<HTMLElement>("[data-works-filter-option]");
1464	      if (!option) return;
1465	      const raw = option.dataset.category?.trim() ?? "";
