1474	      this.uiRuntime?.syncViewLinks(category);
1475	      this._syncScatterUrl(category);
1476	      closePanel();
1477	    };
1478	    filterPanel.addEventListener("click", onPanelClick);
1479	    this._scatterFilterCleanup.push(() =>
1480	      filterPanel.removeEventListener("click", onPanelClick),
1481	    );
1482	
1483	    const onDocumentClick = (event: MouseEvent): void => {
1484	      if (!wrap.contains(event.target as Node)) {
1485	        closePanel();
1486	      }
1487	    };
1488	    document.addEventListener("click", onDocumentClick);
1489	    this._scatterFilterCleanup.push(() =>
1490	      document.removeEventListener("click", onDocumentClick),
1491	    );
1492	
1493	    const onKeyDown = (event: KeyboardEvent): void => {
1494	      if (event.key !== "Escape") return;
1495	      closePanel();
1496	    };
1497	    document.addEventListener("keydown", onKeyDown);
1498	    this._scatterFilterCleanup.push(() =>
1499	      document.removeEventListener("keydown", onKeyDown),
1500	    );
1501	
1502	    this._scatterFilterCleanup.push(() => {
1503	      clearCloseAriaTimer();
1504	      if (!filterPanel.classList.contains("is-open")) {
1505	        filterPanel.setAttribute("aria-hidden", "true");
1506	      }
1507	    });
1508	  }
